(function(E){ const x = E["sales-m3"] = E["sales-m3"] || {units:{}}; x.units["sales-3-1"] = {"grammar":{"id":"c-sales-3-1-g","level":"B1","course":"sales","unit":"sales-3-1","title":"Agree, then answer: although, however, despite","titleTr":"Önce kabul et, sonra cevap ver: although, however, despite","titleFa":"اول بپذیر، بعد جواب بده: although، however، despite","formsTable":{"headers":{"en":["Word","What follows","Example"],"tr":["Kelime","Ardından ne gelir","Örnek"],"fa":["کلمه","بعدش چه می‌آید","مثال"]},"rows":[["although / even though","a clause (subject + verb), no but","Although our price is higher, the total cost is lower."],["However,","a new sentence, after a full stop","Our price is higher. However, ..."],["despite","a noun","Despite the higher price, ..."]]},"wrong":"Although our price is higher, but the total cost is lower.","right":"Although our price is higher, the total cost is lower.","blank":{"sentence":"___ the tiles take eight weeks, they are made to your size.","word":"Although","distractors":["However","But"]},"wrong2":"Despite our price is higher, the total cost is lower.","right2":"Despite the higher price, the total cost is lower.","blank2":{"sentence":"Our price is higher. ___, it includes freight to your port.","word":"However","distractors":["Even though","Despite"],"hint2":{"en":"The gap starts a new sentence after a full stop, and a comma follows it. Which linker can do that?","tr":"Boşluk, noktadan sonra yeni bir cümle başlatıyor ve ardından virgül geliyor. Hangi bağlaç bunu yapabilir?","fa":"جای خالی بعد از نقطه یک جمله‌ی تازه را شروع می‌کند و بعدش ویرگول آمده. کدام کلمه‌ی ربط می‌تواند این کار را بکند؟"},"why":{"en":"However: it starts a new sentence and takes a comma. 'Even though' must join two parts inside one sentence, and 'despite' needs a noun after it.","tr":"However: yeni bir cümle başlatır ve ardından virgül alır. 'Even though' iki parçayı tek cümle içinde bağlamalıdır; 'despite' ise arkasından isim ister.","fa":"⁨However⁩: یک جمله‌ی تازه را شروع می‌کند و بعدش ویرگول می‌آید. ⁨Even though⁩ باید دو بخش را در یک جمله به هم وصل کند و ⁨despite⁩ بعد از خودش اسم می‌خواهد."}},"expParts":{"tryFrom":"blank","rule":[{"en":"Although already links the two parts, so don't add but.","tr":"although iki kısmı zaten bağlar; bu yüzden but ekleme.","fa":"کلمه‌ی although خودش دو بخش جمله را به هم وصل می‌کند، پس دیگر but نیاور.","ex":"Although our price is higher, the total cost is lower."},{"en":"However can't join two sentences, so start a new one with it.","tr":"However iki cümleyi bağlayamaz; bu yüzden yeni bir cümleye onunla başla.","fa":"کلمه‌ی However دو جمله را به هم وصل نمی‌کند، پس جمله‌ی تازه‌ای را با آن شروع کن.","ex":"Our price is higher. However, ..."},{"en":"Despite is a preposition, so a noun follows, never a clause.","tr":"despite bir edattır; ardından isim gelir, asla yan cümle gelmez.","fa":"کلمه‌ی despite حرف اضافه است، پس بعدش اسم می‌آید، نه جمله.","ex":"Despite the higher price, ..."},{"en":"Put the agreement first, so the buyer hears that you listened.","tr":"Önce kabul et ki alıcı dinlediğini anlasın.","fa":"اول موافقت را بگو تا خریدار بفهمد گوش داده‌ای.","ex":"I understand. Although eight weeks is longer, ..."}],"test":{"en":"Count the linking words in one sentence. although + but is one too many.","tr":"Bir cümledeki bağlaçları say. although + but bir fazla.","fa":"حرف‌های ربط یک جمله را بشمار. although + but یکی زیادی است."},"contrast":{"en":"Turkish uses two linkers ('Fiyatımız yüksek olsa da, ama...') and Persian too («با اینکه گران‌تر است، ولی...»), so learners write 'Although..., but...'. English uses one: although OR but.","tr":"Türkçede bazen iki bağlaç birlikte kullanılır: 'Fiyatımız daha yüksek olsa da ama toplam maliyet daha düşük.' İngilizcede yalnızca biri olur: ya although ya but.","fa":"در فارسی دو حرف ربط با هم می‌آیند: «با اینکه قیمتمان بالاتر است، ولی هزینه‌ی کل کمتر است». برای همین خیلی از ما می‌نویسیم Although..., but.... انگلیسی فقط یکی را می‌خواهد: although یا but."}},"errorWatch":[{"find":["despite our price is","despite the price is","despite it is","despite they are","despite we are","despite your supplier is"],"fix":{"en":"despite + a noun: 'Despite the higher price, ...'. With a clause, use although.","tr":"despite + isim: 'Despite the higher price, ...'. Cümleyle although kullan.","fa":"بعد از despite اسم می‌آید: «Despite the higher price, ...». اگر جمله داری، از although استفاده کن."}},{"find":["but however","and however","although but","even though but"],"fix":{"en":"Use one linking word: 'Our price is higher. However, ...'.","tr":"Tek bağlaç kullan: 'Our price is higher. However, ...'.","fa":"یک حرف ربط به کار ببر: «Our price is higher. However, ...»."}}]},"b2":{"id":"c-sales-3-1-b2","level":"B2","track":"B2","course":"sales","unit":"sales-3-1","title":"Contrasting two offers: whereas, on the other hand","titleTr":"İki teklifi karşılaştırmak: whereas, on the other hand","titleFa":"مقایسه‌ی دو پیشنهاد: whereas و on the other hand","formsTable":{"headers":{"en":["Linker","Use","Example"],"tr":["Bağlaç","Kullanım","Örnek"],"fa":["حرف ربط","کاربرد","مثال"]},"rows":[["whereas","two facts in one sentence","Whereas their price is FOB, ours is CIF."],["On the other hand,","a second point, new sentence","Our lead time is longer. On the other hand, we pack to order."],["On the contrary,","says the opposite is true","\"Too late for spring?\" \"On the contrary, it arrives in March.\""]]},"wrong":"Our lead time is longer. On the contrary, we pack to order.","right":"Our lead time is longer. On the other hand, we pack to order.","blank":{"sentence":"Their prices are lower. On the ___ hand, they only sell full containers.","word":"other","distractors":["contrary","another"]},"wrong2":"Whereas their price is FOB, but ours is CIF.","right2":"Whereas their price is FOB, ours is CIF.","blank2":{"sentence":"___ their quote is valid for a week, ours is valid for a month.","word":"Whereas","distractors":["Despite","On the other hand"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"whereas + clause, then the other clause. No but.","tr":"whereas + yan cümle, sonra diğer cümle. but yok.","fa":"بعد از whereas جمله می‌آید و بعد جمله‌ی دیگر؛ دیگر but نیاور.","ex":"Whereas their price is FOB, ours is CIF."},{"en":"On the other hand, = a second point, in a new sentence.","tr":"On the other hand, = ikinci bir nokta, yeni bir cümlede.","fa":"عبارت On the other hand نکته‌ی دوم را در جمله‌ای تازه می‌آورد.","ex":"It takes longer. On the other hand, we pack to order."},{"en":"On the contrary, = 'No, the opposite is true.'","tr":"On the contrary, = 'Hayır, tam tersi doğru.'","fa":"عبارت On the contrary یعنی «نه، برعکسش درست است».","ex":"\"Too late?\" \"On the contrary, ...\""}],"test":{"en":"Can you start with 'No,...'? Then On the contrary. If both points are true, On the other hand.","tr":"'Hayır,...' diye başlayabiliyor musun? O zaman On the contrary. İki nokta da doğruysa On the other hand.","fa":"می‌توانی با «نه، ...» شروع کنی؟ پس On the contrary. اگر هر دو نکته درست است، On the other hand."},"contrast":{"en":"Turkish 'aksine' and Persian «برعکس» are often used for 'on the other hand' in speech, so learners write 'On the contrary' for any contrast. In English it only rejects a statement.","tr":"Türkçede 'aksine' bazen 'öte yandan' anlamında kullanılıyor; bu yüzden her karşıtlıkta 'On the contrary' yazılıyor. İngilizcede bu ifade yalnızca bir söylenenin tersini savunur. 'Öte yandan' = On the other hand.","fa":"در فارسی «برعکس» گاهی به معنی «از طرف دیگر» به کار می‌رود؛ برای همین خیلی از ما برای هر تضادی On the contrary می‌نویسیم. در انگلیسی این عبارت فقط حرف قبلی را رد می‌کند. «از طرف دیگر» یعنی On the other hand."}},"errorWatch":[{"find":["on the contrary, it lasts","on the contrary, ours","on the contrary, our","on the contrary, we pack"],"fix":{"en":"For a second point, use 'On the other hand'. 'On the contrary' says the opposite of what was just said.","tr":"İkinci bir nokta için 'On the other hand' kullan. 'On the contrary' az önce söylenenin tersini söyler.","fa":"برای نکته‌ی دوم «On the other hand» به کار ببر. «On the contrary» یعنی عکس حرف قبلی درست است."}}],"useIn":{"en":"B2: set the two offers side by side once with whereas or On the other hand.","tr":"B2: iki teklifi bir kez whereas ya da On the other hand ile yan yana koy.","fa":"مسیر B2: یک بار دو پیشنهاد را با whereas یا On the other hand کنار هم بگذار."},"exitItem":{"from":"sales-3-1","kind":"blank","prompt":"Our cartons cost more. On the other ___, fewer break on the way.","options":["side","way","hand"],"correct":2,"why":{"en":"hand: the fixed phrase is 'on the other hand'. 'Side' and 'way' don't make this contrast.","tr":"hand: sabit ifade 'on the other hand'dir. 'Side' ve 'way' bu karşıtlığı kurmaz.","fa":"hand درست است، چون عبارت ثابت on the other hand است. side و way این تقابل را نمی‌سازند."},"hint2":{"en":"Both points are true, so you need the fixed phrase for the second side. It uses a part of your body.","tr":"İki nokta da doğru, bu yüzden ikinci taraf için kalıp ifadeyi kullan. İçinde vücudunun bir parçası var.","fa":"هر دو نکته درست است، پس برای طرف دوم عبارت ثابتش را لازم داری. در آن اسم یکی از اعضای بدن هست."}}},"vocab":{"id":"c-sales-3-1-v","level":"B1","category":"vocab","course":"sales","unit":"sales-3-1","goals":["career"],"title":{"en":"Objections and price","tr":"İtirazlar ve fiyat","fa":"اعتراض و قیمت"},"cards":[{"word":"objection","sentence":"The main objection is the lead time.","meaning":{"en":"A reason a buyer gives for not buying.","tr":"itiraz.","fa":"اعتراض؛ دلیلی که خریدار برای نخریدن می‌آورد"}},{"word":"competitor","sentence":"Our competitor sells only full containers.","meaning":{"en":"Another company that sells the same thing.","tr":"rakip.","fa":"رقیب"}},{"word":"discount","sentence":"Don't offer a discount in the first minute.","meaning":{"en":"Money taken off the price.","tr":"indirim.","fa":"تخفیف"}},{"word":"like with like","sentence":"Compare like with like: both prices on CIF terms.","meaning":{"en":"Two things of the same kind and size, so the comparison is fair.","tr":"aynı türden şeyleri (karşılaştırmak).","fa":"مقایسه‌ی دو چیز هم‌ارز و هم‌جنس"}},{"word":"total cost","sentence":"The total cost includes freight, duty and waste.","meaning":{"en":"All the money something costs, not only the price.","tr":"toplam maliyet.","fa":"هزینه‌ی کل"}},{"word":"justify","sentence":"Can you justify the higher price?","meaning":{"en":"To give good reasons for something.","tr":"gerekçelendirmek, haklı çıkarmak.","fa":"توجیه کردن"}},{"word":"reasonable","sentence":"Thirty days is a reasonable lead time.","meaning":{"en":"Fair and sensible.","tr":"makul.","fa":"معقول"}},{"word":"switch","sentence":"It takes time for a chain to switch to a new supplier.","meaning":{"en":"To change from one thing to another.","tr":"değiştirmek, geçmek.","fa":"عوض کردن"}},{"word":"risk","sentence":"What is the risk of changing supplier now?","meaning":{"en":"The chance that something bad happens.","tr":"risk.","fa":"ریسک؛ خطر"}},{"word":"concern","sentence":"His main concern is delivery in winter.","meaning":{"en":"A worry.","tr":"endişe.","fa":"نگرانی"}}]},"judge":{"id":"c-sales-3-1-j","course":"sales","unit":"sales-3-1","type":"judge","title":{"en":"Good answer to 'too expensive'?","tr":"'Too expensive' için iyi cevap mı?","fa":"جواب خوب به «too expensive»؟"},"prompt":"A buyer of carpets says: \"Your price is too high.\" Four answers.","parts":["Agrees first","Asks why","Gives a reason"],"instruction":{"en":"Tap what each answer does. The best answer does all three.","tr":"Her cevabın ne yaptığına dokun. En iyi cevap üçünü de yapar.","fa":"روی کاری که هر جواب می‌کند بزن. بهترین جواب هر سه را دارد."},"items":[{"by":"New rep","answer":"OK, I can take off 10%. Is that better?","present":[],"fix":{"en":"You gave away money and learned nothing. Ask first: 'Compared with what, and on which terms?'","tr":"Para verdin ve hiçbir şey öğrenmedin. Önce sor: 'Compared with what, and on which terms?'","fa":"پولت را از دست دادی و چیزی هم نفهمیدی. اول بپرس: «Compared with what, and on which terms?»"}},{"by":"Sales rep","answer":"No, it isn't. Our carpets are the best on the market.","present":[],"fix":{"en":"You're arguing, with no proof. Agree with the true part, then give one fact.","tr":"Tartışıyorsun ve kanıtın yok. Doğru kısmı kabul et, sonra tek bir gerçek söyle.","fa":"داری بحث می‌کنی و مدرکی نداری. با بخش درست موافقت کن، بعد یک واقعیت بگو."}},{"by":"AI tool","answer":"I completely understand your frustration, and your feedback is very valuable to us. Could you share which offer you are comparing?","present":["Agrees first","Asks why"],"fix":{"en":"Good question, but the first line is padding, and there is no reason yet. Say 'I understand', ask, then give your reason.","tr":"Soru iyi ama ilk satır dolgu ve henüz neden yok. 'I understand' de, sor, sonra nedenini söyle.","fa":"سؤال خوب است، ولی خط اول اضافی است و هنوز دلیلی نیاورده‌ای. بگو «I understand»، بپرس و بعد دلیلت را بگو."}},{"by":"Good model","answer":"I understand. Which offer are you comparing it with? Although our price is higher, ours is pure wool, and the lab report is yours to check.","present":["Agrees first","Asks why","Gives a reason"],"fix":null}]},"speaking":{"id":"sales-3-1","course":"sales","unit":"sales-3-1","topic":{"en":"Answering three objections","tr":"Üç itiraza cevap vermek","fa":"جواب دادن به سه اعتراض"},"warmup":{"en":"What objection do you hear most often, or expect to hear?","tr":"En sık hangi itirazı duyuyorsun ya da duymayı bekliyorsun?","fa":"کدام اعتراض را بیشتر می‌شنوی، یا انتظار داری بشنوی؟"},"questions":[{"en":"The buyer says: 'You're 15% more expensive.' Pause, agree, ask, answer.","tr":"Alıcı diyor ki: 'You're 15% more expensive.' Dur, kabul et, sor, cevap ver.","fa":"خریدار می‌گوید: «You're 15% more expensive.» مکث کن، موافقت کن، بپرس، جواب بده."},{"en":"The buyer says: 'We're happy with our current supplier.' Answer, and ask for one small test order.","tr":"Alıcı diyor ki: 'We're happy with our current supplier.' Cevap ver ve küçük bir deneme siparişi iste.","fa":"خریدار می‌گوید: «We're happy with our current supplier.» جواب بده و یک سفارش آزمایشی کوچک بخواه."},{"en":"The buyer says: 'Six weeks is too long.' Use although or however.","tr":"Alıcı diyor ki: 'Six weeks is too long.' Although ya da however kullan.","fa":"خریدار می‌گوید: «Six weeks is too long.» از although یا however استفاده کن."}],"followups":[{"en":"Say your answer to the objection you fear most.","tr":"En çok korktuğun itiraza cevabını söyle.","fa":"جوابت را به اعتراضی که بیشتر از همه از آن می‌ترسی بگو."}],"expressions":[{"phrase":"I understand.","meaning":{"en":"Shows you heard, and changes nothing yet.","tr":"Anladığını gösterir; henüz hiçbir şeyi değiştirmez.","fa":"نشان می‌دهد شنیده‌ای و فعلاً چیزی را تغییر نمی‌دهد."}},{"phrase":"Compared with what?","meaning":{"en":"Finds the other price and terms.","tr":"Diğer fiyatı ve koşulları bulur.","fa":"قیمت و شرایط دیگر را روشن می‌کند."}},{"phrase":"Although ..., ...","meaning":{"en":"Agrees, then makes your point.","tr":"Kabul eder, sonra asıl noktanı söyler.","fa":"اول می‌پذیرد، بعد حرف اصلی‌ات را می‌گوید."}}],"model":"I understand. Which price are you comparing it with, and on which terms? I see. Although our unit price is higher, it includes freight to your port. On the same terms, the gap is about two percent. And it's good that you have a supplier you trust. However, could we start with one small test order, so you have a second option?","selfCheck":[{"en":"I paused and didn't interrupt.","tr":"Durakladım, sözünü kesmedim.","fa":"مکث کردم و حرفش را قطع نکردم."},{"en":"I asked before I answered.","tr":"Cevap vermeden önce sordum.","fa":"قبل از جواب دادن پرسیدم."},{"en":"I used one linker in each sentence.","tr":"Her cümlede tek bağlaç kullandım.","fa":"در هر جمله یک حرف ربط به کار بردم."},{"en":"I offered no discount.","tr":"İndirim önermedim.","fa":"تخفیف پیشنهاد ندادم."}]},"writing":{"id":"c-sales-3-1-w","course":"sales","unit":"sales-3-1","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your objection sheet","tr":"İtiraz sayfan","fa":"برگه‌ی اعتراض‌های تو"},"portfolio":"sales-final-4","prompt":{"en":"Write answers to three objections for your own product, or for hand-made carpets (pure wool, a lab report, your exact size and colour): 'too expensive', 'we have a supplier', 'eight weeks is too long' (70-100 words). For each one: agree, ask one question, then answer with although, however or despite. Offer no discount.","tr":"Kendi ürünün ya da el dokuması halılar (saf yün, laboratuvar raporu, istenen ölçü ve renk) için üç itiraza cevap yaz: 'too expensive', 'we have a supplier', 'eight weeks is too long' (70-100 kelime). Her biri için: kabul et, bir soru sor, sonra although, however ya da despite ile cevap ver. İndirim önerme.","fa":"برای محصول خودت، یا فرش دستباف (پشم خالص، گزارش آزمایشگاه، اندازه و رنگ دلخواه)، به سه اعتراض جواب بنویس: «too expensive»، «we have a supplier»، «eight weeks is too long» (۷۰ تا ۱۰۰ کلمه). برای هر کدام: موافقت کن، یک سؤال بپرس، بعد با although، however یا despite جواب بده. تخفیف پیشنهاد نکن."},"model":"\"Too expensive.\" I understand. Which offer are you comparing it with? Although our price is higher, these carpets are pure wool, with a lab report.\n\n\"We have a supplier.\" That's good. What would you change about them, if you could? However, a second source protects you if they run late.\n\n\"Eight weeks is too long.\" I agree that it's a long time. When do you need the carpets? Despite the wait, you get your exact size and colour.","frame":"\"Too expensive.\" I understand. ___? Although ___, ___.\n\n\"We have a supplier.\" That's good. ___? However, ___.\n\n\"___ is too long.\" I agree that ___. ___? Despite ___, ___.","words":[{"word":"Although"},{"word":"However"},{"word":"Despite"}],"minWords":70,"minSentences":6,"rubric":["Task done: three objections, each with agreement, a question and an answer","Organised: same order every time; no discount","Language: although, however and despite are correct","Tone: calm and respectful; no attack on competitors"],"rubricI18n":{"tr":["Görev: üç itiraz; her birinde kabul, soru ve cevap","Düzen: her seferinde aynı sıra; indirim yok","Dil: although, however ve despite doğru","Üslup: sakin ve saygılı; rakiplere saldırı yok"],"fa":["کامل بودن کار: سه اعتراض، هر کدام با موافقت، سؤال و جواب","نظم: هر بار همان ترتیب؛ بدون تخفیف","زبان: although، however و despite درست‌اند","لحن: آرام و محترمانه؛ بدون حمله به رقیب‌ها"]},"parts":[{"t":{"en":"Agree with what is true","tr":"Doğru olan kısmı kabul et","fa":"بخشی را که درست است قبول کن"},"find":["i understand","i agree","that's good","you're right","that's true","fair point"],"sample":"price: I understand · supplier: that's good · eight weeks: I agree it's long"},{"t":{"en":"Ask one question each time","tr":"Her seferinde tek bir soru sor","fa":"هر بار یک سؤال بپرس"},"find":["compared with","which offer","which price","what would","when do you","what are you comparing"],"sample":"which offer are you comparing? · what would you change? · when do you need them?"},{"t":{"en":"Answer with although, however or despite","tr":"although, however ya da despite ile cevap ver","fa":"با ⁨although⁩، ⁨however⁩ یا ⁨despite⁩ جواب بده"},"find":["although","however","despite","even though"],"sample":"although higher: pure wool, lab report · however: a second source · despite the wait: your exact size"}]},"exit":{"id":"c-sales-3-1-x","course":"sales","unit":"sales-3-1","type":"exit","items":[{"from":"sales-3-1","kind":"blank","prompt":"___ the higher unit price, the total cost is lower.","options":["Although","Despite","However"],"correct":1,"point":2,"why":{"en":"Despite: it goes before a noun phrase: despite the higher price. 'Although' needs a full clause, and 'However' starts a new sentence.","tr":"Despite: bir isim öbeğinden önce gelir: despite the higher price. 'Although' tam bir yan cümle ister; 'However' yeni bir cümle başlatır.","fa":"Despite درست است، چون قبل از گروه اسمی می‌آید: despite the higher price. although جمله‌ی کامل می‌خواهد و however جمله‌ی تازه شروع می‌کند."},"hint2":{"en":"After the gap comes a noun phrase, not a subject and a verb. Which linker goes before a noun?","tr":"Boşluktan sonra özne ve fiil değil, bir isim öbeği geliyor. Hangi bağlaç bir ismin önüne gelir?","fa":"بعد از جای خالی یک گروه اسمی آمده، نه فاعل و فعل. کدام کلمه‌ی ربط قبل از اسم می‌آید؟"}},{"from":"sales-3-1","kind":"mcq","prompt":"A buyer says \"too expensive\". What should you do first?","options":["Give 5% off.","Ask what they are comparing it with.","Say that competitors are worse."],"correct":1,"point":1,"why":{"en":"Ask what they compare it with: 'too expensive' always means 'than something'. A quick 5% gives money away; attacking rivals sounds weak.","tr":"Neyle karşılaştırdığını sor: 'too expensive' her zaman 'bir şeye göre' demektir. Hemen %5 indirim parayı boşa verir; rakiplere saldırmak zayıf duyulur.","fa":"بپرس با چه چیزی مقایسه می‌کند، چون «too expensive» همیشه یعنی گران‌تر از چیزی. ۵ درصد تخفیف فوری پول را هدر می‌دهد و بد گفتن از رقیب ضعیف به نظر می‌رسد."},"hint2":{"en":"You can't answer a worry you don't understand yet. What do you need to find out before you answer?","tr":"Henüz anlamadığın bir endişeye cevap veremezsin. Cevap vermeden önce neyi öğrenmen gerekir?","fa":"به نگرانی‌ای که هنوز نفهمیدی چیست نمی‌توانی جواب بدهی. قبل از جواب دادن باید چه چیزی را بفهمی؟"}},{"from":"sales-3-1","kind":"mcq","prompt":"What does \"compare like with like\" mean?","options":["Compare two offers on the same terms and size.","Compare your best price with their worst.","Compare only products you like."],"correct":0,"point":1,"why":{"en":"Same terms and the same size: only then is the price difference real. Comparing your best price with their worst is not fair.","tr":"Aynı koşullar ve aynı miktar: fiyat farkı ancak o zaman gerçektir. Kendi en iyi fiyatınla onların en kötüsünü karşılaştırmak adil değildir.","fa":"با شرایط و اندازه‌ی یکسان؛ فقط آن وقت فرق قیمت واقعی است. مقایسه‌ی بهترین قیمت خودت با بدترین قیمت آن‌ها منصفانه نیست."},"hint2":{"en":"Two offers can only be compared when everything else is equal. What must be the same in both?","tr":"İki teklif ancak diğer her şey eşit olduğunda karşılaştırılabilir. İkisinde neyin aynı olması gerekir?","fa":"دو پیشنهاد را فقط وقتی می‌شود مقایسه کرد که بقیه‌ی چیزها یکی باشد. چه چیزی باید در هر دو یکسان باشد؟"}},{"from":"sales-2-3","kind":"blank","prompt":"If the buyer ___ by Monday, we can keep this price.","options":["pays","will pay","paid"],"correct":0,"point":2,"why":{"en":"pays: in a real condition, 'if' takes the present. 'Will pay' is wrong after if, and 'paid' makes it unreal.","tr":"pays: gerçek koşulda 'if' geniş zaman alır. if'ten sonra 'will pay' yanlıştır; 'paid' koşulu hayalî yapar.","fa":"pays درست است، چون در شرط واقعی بعد از if حال ساده می‌آید. will pay بعد از if غلط است و paid شرط را غیرواقعی می‌کند."}},{"from":"sales-2-1","kind":"mcq","prompt":"Which four things qualify a lead?","options":["Need, volume, who decides, when","Name, age, hobby, city","Logo, website, office, staff"],"correct":0,"point":1,"why":{"en":"Need, volume, who decides and when: together they show a real buyer. Hobbies or an office say nothing about buying.","tr":"İhtiyaç, hacim, karar veren ve zaman: birlikte gerçek bir alıcıyı gösterir. Hobi ya da ofis satın almayla ilgili bir şey söylemez.","fa":"نیاز، حجم، تصمیم‌گیرنده و زمان با هم خریدار واقعی را نشان می‌دهند. سرگرمی یا دفتر چیزی درباره‌ی خرید نمی‌گویند."},"hint2":{"en":"A real buyer has a reason to buy, enough to buy, the power to decide and a time. Which list checks those?","tr":"Gerçek bir alıcının satın almak için bir nedeni, yeterli miktarı, karar yetkisi ve bir zamanı vardır. Hangi liste bunları kontrol ediyor?","fa":"خریدار واقعی دلیلی برای خرید دارد، به اندازه‌ی کافی می‌خرد، اختیار تصمیم دارد و زمانش هم معلوم است. کدام فهرست این‌ها را می‌سنجد؟"}},{"from":"sales-1-2","kind":"blank","prompt":"Do you know ___ the buyer is back today?","options":["if","is","does"],"correct":0,"point":2,"why":{"en":"if: 'Do you know if...' asks a yes/no question politely. 'Is' and 'does' would put two question forms in one sentence.","tr":"if: 'Do you know if...' kibarca evet/hayır sorusu sorar. 'Is' ve 'does' tek cümlede iki soru yapısı oluşturur.","fa":"if درست است، چون Do you know if... سؤال بله‌یا‌نه را مؤدبانه می‌پرسد. is و does در یک جمله دو ساختار سؤالی می‌سازند."},"hint2":{"en":"The question inside is a yes/no one. Which small word brings a yes/no question into a longer sentence?","tr":"İçerideki soru evet/hayır sorusu. Hangi küçük kelime evet/hayır sorusunu daha uzun bir cümlenin içine taşır?","fa":"سؤالِ داخل جمله از نوع بله/نه است. کدام کلمه‌ی کوچک سؤال بله/نه را وارد یک جمله‌ی بلندتر می‌کند؟"}}]},"explain":{"id":"c-sales-3-1-e","course":"sales","unit":"sales-3-1","type":"explain","level":"B1","title":{"en":"Answering objections without a discount","tr":"İtirazlara indirimsiz cevap vermek","fa":"جواب به اعتراض‌ها بدون تخفیف"},"objective":{"en":"After this lesson, you can answer price and supplier objections calmly, without giving a discount too early.","tr":"Bu dersin sonunda fiyat ve tedarikçi itirazlarına, erkenden indirim vermeden sakince cevap verebileceksin.","fa":"بعد از این درس می‌توانی به اعتراض‌های مشتری درباره‌ی قیمت و تأمین‌کننده آرام جواب بدهی، بدون اینکه زود تخفیف بدهی."},"hook":{"en":"When a buyer says 'too expensive', find out what they mean before you change the price. Often it means: show me why. An early discount only says your first price was not real.","tr":"Alıcı 'too expensive' dediğinde, fiyatı değiştirmeden önce ne demek istediğini öğren. Çoğu zaman anlamı şudur: nedenini göster. Erken indirim yalnızca ilk fiyatının gerçek olmadığını söyler.","fa":"وقتی خریدار می‌گوید «too expensive»، قبل از تغییر قیمت بفهم منظورش چیست. خیلی وقت‌ها یعنی: دلیلش را نشانم بده. تخفیف زودهنگام فقط می‌گوید قیمت اولت واقعی نبوده است."},"before":{"en":"A buyer says your price is too high. Write your answer.","tr":"Bir alıcı fiyatının çok yüksek olduğunu söylüyor. Cevabını yaz.","fa":"یک خریدار می‌گوید قیمتت خیلی بالاست. جوابت را بنویس."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Four moves for any objection","tr":"Her itiraz için dört adım","fa":"چهار قدم برای هر اعتراض"},"steps":[{"en":"Pause and let them finish. If you speed up, you sound worried.","tr":"Dur ve bitirmelerini bekle. Hızlanırsan endişeli görünürsün.","fa":"مکث کن و بگذار حرفشان تمام شود. اگر تندتر حرف بزنی، نگران به نظر می‌رسی.","ex":"(Silence for two seconds.)"},{"en":"Agree with what is true. Then they stop defending their point and listen.","tr":"Doğru olan kısmı kabul et. Böylece kendi görüşlerini savunmayı bırakıp dinlerler.","fa":"با بخشی که درست است موافقت کن. این‌طوری دیگر از حرفشان دفاع نمی‌کنند و گوش می‌دهند.","ex":"You're right, our unit price is higher."},{"en":"Ask what is behind it, so you answer the real worry.","tr":"Arkasında ne olduğunu sor ki gerçek endişeye cevap verebilesin.","fa":"بپرس پشت این حرف چیست تا به نگرانی واقعی جواب بدهی.","ex":"Compared with what? Which terms is that price on?"},{"en":"Answer only that. Compare like with like: same goods, same terms. Then check they agree.","tr":"Yalnızca buna cevap ver. Aynı şeyleri karşılaştır: aynı ürün, aynı koşullar. Sonra ikna olup olmadıklarını sor.","fa":"فقط به همان جواب بده. چیزهای یکسان را مقایسه کن: کالای یکسان، شرایط یکسان. بعد بپرس قانع شده‌اند یا نه.","ex":"On the same terms, the gap is 2%. Does that help?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Agree, then answer: although, however, despite","tr":"Önce kabul et, sonra cevap ver: although, however, despite","fa":"اول بپذیر، بعد جواب بده: although، however، despite"},"steps":[{"en":"Although already links the two parts, so don't add but.","tr":"although iki kısmı zaten bağlar; bu yüzden but ekleme.","fa":"کلمه‌ی although خودش دو بخش جمله را به هم وصل می‌کند، پس دیگر but نیاور.","ex":"Although our price is higher, the total cost is lower."},{"en":"However can't join two sentences, so start a new one with it.","tr":"However iki cümleyi bağlayamaz; bu yüzden yeni bir cümleye onunla başla.","fa":"کلمه‌ی However دو جمله را به هم وصل نمی‌کند، پس جمله‌ی تازه‌ای را با آن شروع کن.","ex":"Our price is higher. However, ..."},{"en":"Despite is a preposition, so a noun follows, never a clause.","tr":"despite bir edattır; ardından isim gelir, asla yan cümle gelmez.","fa":"کلمه‌ی despite حرف اضافه است، پس بعدش اسم می‌آید، نه جمله.","ex":"Despite the higher price, ..."},{"en":"Put the agreement first, so the buyer hears that you listened.","tr":"Önce kabul et ki alıcı dinlediğini anlasın.","fa":"اول موافقت را بگو تا خریدار بفهمد گوش داده‌ای.","ex":"I understand. Although eight weeks is longer, ..."}],"table":{"headers":{"en":["Word","What follows","Example"],"tr":["Kelime","Ardından ne gelir","Örnek"],"fa":["کلمه","بعدش چه می‌آید","مثال"]},"rows":[["although / even though","a clause (subject + verb), no but","Although our price is higher, the total cost is lower."],["However,","a new sentence, after a full stop","Our price is higher. However, ..."],["despite","a noun","Despite the higher price, ..."]]},"tip":{"en":"Turkish uses two linkers ('Fiyatımız yüksek olsa da, ama...') and Persian too («با اینکه گران‌تر است، ولی...»), so learners write 'Although..., but...'. English uses one: although OR but.","tr":"Türkçede bazen iki bağlaç birlikte kullanılır: 'Fiyatımız daha yüksek olsa da ama toplam maliyet daha düşük.' İngilizcede yalnızca biri olur: ya although ya but.","fa":"در فارسی دو حرف ربط با هم می‌آیند: «با اینکه قیمتمان بالاتر است، ولی هزینه‌ی کل کمتر است». برای همین خیلی از ما می‌نویسیم Although..., but.... انگلیسی فقط یکی را می‌خواهد: although یا but."},"wrong":"Despite our price is higher, you save on returns.","right":"Although our price is higher, you save on returns."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Prepare the common objections","tr":"Sık itirazlara hazırlan","fa":"برای اعتراض‌های رایج آماده شو"},"body":{"en":"Most objections are common ones: price, 'we have a supplier', 'not now', 'I must ask my boss'. Write and practise an answer to each. Don't attack a competitor, because buyers stop trusting you; compare facts.","tr":"İtirazların çoğu sık görülenlerdir: fiyat, 'tedarikçimiz var', 'şimdi değil', 'patronuma sormalıyım'. Her birine bir cevap yaz ve çalış. Rakibini kötüleme, çünkü alıcının sana güveni azalır; gerçekleri karşılaştır.","fa":"بیشتر اعتراض‌ها همان اعتراض‌های رایج‌اند: قیمت، «تأمین‌کننده داریم»، «الان نه»، «باید از رئیسم بپرسم». برای هر کدام جوابی بنویس و تمرینش کن. از رقیب بدگویی نکن، چون خریدار به تو بی‌اعتماد می‌شود؛ واقعیت‌ها را مقایسه کن."},"phrases":[{"phrase":"I understand.","meaning":{"en":"Shows you heard, and changes nothing yet.","tr":"Anladığını gösterir; henüz hiçbir şeyi değiştirmez.","fa":"نشان می‌دهد شنیده‌ای و فعلاً چیزی را تغییر نمی‌دهد."}},{"phrase":"Compared with what?","meaning":{"en":"Finds the other price and terms.","tr":"Diğer fiyatı ve koşulları bulur.","fa":"قیمت و شرایط دیگر را روشن می‌کند."}},{"phrase":"Although ..., ...","meaning":{"en":"Agrees, then makes your point.","tr":"Kabul eder, sonra asıl noktanı söyler.","fa":"اول می‌پذیرد، بعد حرف اصلی‌ات را می‌گوید."}},{"phrase":"objection","meaning":{"en":"A reason a buyer gives for not buying.","tr":"itiraz.","fa":"اعتراض؛ دلیلی که خریدار برای نخریدن می‌آورد"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Answer before you cut the price","tr":"Fiyatı indirmeden önce cevap ver","fa":"قبل از کم کردن قیمت جواب بده"},"item":"Too expensive? OK, I can give you 10% off. Your facts: your price includes freight to the buyer's port; the other offer may be FOB.","answer":"I understand. Which price are you comparing it with, and on which terms? Although our unit price is higher, our price includes freight to your port.","walk":[{"en":"An instant discount tells the buyer your first price was not real.","tr":"Anında indirim, alıcıya ilk fiyatının gerçek olmadığını söyler.","fa":"تخفیف فوری به خریدار می‌گوید قیمت اولت واقعی نبوده است."},{"en":"Ask first. Their price may be FOB, and yours CIF.","tr":"Önce sor. Onların fiyatı FOB, seninki CIF olabilir.","fa":"اول بپرس. شاید قیمت آن‌ها FOB باشد و قیمت تو CIF."},{"en":"Agree with the true part, then give one reason.","tr":"Doğru kısmı kabul et, sonra tek bir neden söyle.","fa":"با بخش درست موافقت کن، بعد یک دلیل بیاور."}],"cut":["I can give you 10% off"],"cutHint":{"en":"Tap the discount given before any question.","tr":"Hiçbir soru sorulmadan verilen indirime dokun.","fa":"روی تخفیفی بزن که قبل از هر سؤالی داده شده."}},"quick":{"prompt":"When a buyer says \"too expensive\", first ask: ___","options":["\"Compared with what?\"","\"How about 10% off?\"","\"Why don't you trust us?\""],"correct":0,"why":{"en":"\"Compared with what?\": you need the other price and its terms before you can compare like with like.","tr":"\"Compared with what?\": aynı şartlarda karşılaştırmak için diğer fiyatı ve koşullarını bilmen gerekir.","fa":"جواب Compared with what? است، چون برای مقایسه‌ی منصفانه باید قیمت دیگر و شرایطش را بدانی."}},"remember":{"en":"Pause, agree, ask, answer. The discount comes last, if at all. You can now answer 'too expensive' with a calm question and a fair comparison.","tr":"Dur, kabul et, sor, cevap ver. İndirim en son gelir, gelirse. Artık 'too expensive' sözüne sakin bir soru ve adil bir karşılaştırmayla cevap verebilirsin.","fa":"مکث کن، موافقت کن، سؤال بپرس و بعد جواب بده. تخفیف آخر از همه می‌آید، آن هم اگر لازم باشد. حالا می‌توانی به «too expensive» با یک سؤال آرام و مقایسه‌ای منصفانه جواب بدهی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Contrasting two offers: whereas, on the other hand","tr":"İki teklifi karşılaştırmak: whereas, on the other hand","fa":"مقایسه‌ی دو پیشنهاد: whereas و on the other hand"},"steps":[{"en":"whereas + clause, then the other clause. No but.","tr":"whereas + yan cümle, sonra diğer cümle. but yok.","fa":"بعد از whereas جمله می‌آید و بعد جمله‌ی دیگر؛ دیگر but نیاور.","ex":"Whereas their price is FOB, ours is CIF."},{"en":"On the other hand, = a second point, in a new sentence.","tr":"On the other hand, = ikinci bir nokta, yeni bir cümlede.","fa":"عبارت On the other hand نکته‌ی دوم را در جمله‌ای تازه می‌آورد.","ex":"It takes longer. On the other hand, we pack to order."},{"en":"On the contrary, = 'No, the opposite is true.'","tr":"On the contrary, = 'Hayır, tam tersi doğru.'","fa":"عبارت On the contrary یعنی «نه، برعکسش درست است».","ex":"\"Too late?\" \"On the contrary, ...\""}],"table":{"headers":{"en":["Linker","Use","Example"],"tr":["Bağlaç","Kullanım","Örnek"],"fa":["حرف ربط","کاربرد","مثال"]},"rows":[["whereas","two facts in one sentence","Whereas their price is FOB, ours is CIF."],["On the other hand,","a second point, new sentence","Our lead time is longer. On the other hand, we pack to order."],["On the contrary,","says the opposite is true","\"Too late for spring?\" \"On the contrary, it arrives in March.\""]]},"body":{"en":"B2: set the two offers side by side once with whereas or On the other hand.","tr":"B2: iki teklifi bir kez whereas ya da On the other hand ile yan yana koy.","fa":"مسیر B2: یک بار دو پیشنهاد را با whereas یا On the other hand کنار هم بگذار."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
